// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible actor
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // require a deposit strictly above MinDeposit so the balance is set
        uint256 depositAmount = bound(amount, c.MinDeposit() + 1, type(uint96).max);
        uint256 cashOutAmount = depositAmount;

        vm.deal(actor, depositAmount + 1 ether);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // deploy adversarial re-entrant caller that fails on its single re-entry
        ReenterOnCashOut attacker = new ReenterOnCashOut(address(c), cashOutAmount);
        vm.deal(address(attacker), depositAmount + 1 ether);

        // attacker becomes the caller; it will re-enter once during CashOut
        vm.prank(address(attacker));
        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(address(attacker));
        vm.prank(address(attacker));
        try c.CashOut(cashOutAmount) {
            // reference: subtraction already happened, the failed re-entrant withdrawal
            // may revert internally but the outer call should succeed because attacker
            // still had enough balance at the moment of its re-entry.
            // mutant: subtraction happens after the call, so the failed re-entry leaves balance
            // unchanged and the post-call subtraction underflows/reverts.
            uint256 expected = balBefore - cashOutAmount;
            assertTrue(c.balances(address(attacker)) == expected);
        } catch {
            // reference must not revert for this admissible case; mutant does.
            assertTrue(false);
        }
    }
}

contract ReenterOnCashOut {
    Private_Bank private c;
    uint256 private amount;
    bool private entered;

    constructor(address _c, uint256 _amount) {
        c = Private_Bank(payable(_c));
        amount = _amount;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // single re-entrant call; it will fail because the caller does not
            // actually have an extra unspent balance under the correct contract.
            bool ok; try c.CashOut(amount) { ok = true; } catch { ok = false; }
            if (!ok) {
                revert("reentry-failed");
            }
        }
    }
}
